fn pick_max_by_count(c1: Int, c2: Int, xs: List[Int]) -> Int
  requires len(xs) > 0
  ensures (result == c1 or result == c2) and count(xs, result) >= count(xs, c1) and count(xs, result) >= count(xs, c2)
  effects pure
  example pick_max_by_count(1, 2, [1, 2, 2, 3]) == 2
  example pick_max_by_count(5, 1, [5, 5, 5, 1, 1]) == 5
  example pick_max_by_count(2, 2, [1, 2, 2, 3]) == 2
{
  if count_occurrences(xs, c1) > count_occurrences(xs, c2) then c1 else c2
}

fn find_most_in_list(candidates: List[Int], xs: List[Int]) -> Int
  requires len(candidates) > 0 and len(xs) > 0
  ensures contains(candidates, result) and forall y in candidates: count(xs, y) <= count(xs, result)
  effects pure
  example find_most_in_list([1], [1]) == 1
  example find_most_in_list([2, 1], [1, 2, 2, 3]) == 2
  example find_most_in_list([1, 2, 2, 3], [1, 2, 2, 3]) == 2
{
  match candidates {
    [] => 0
    [c, ..t] => match t {
      [] => c
      _ => pick_max_by_count(c, find_most_in_list(t, xs), xs)
    }
  }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires xs == [] or (exists x in xs: forall y in xs: y == x or count(xs, x) > count(xs, y))
  ensures match result {
    None => xs == []
    Some(v) => len(xs) > 0 and contains(xs, v) and forall y in xs: count(xs, y) <= count(xs, v)
  }
  effects pure
  example most_frequent([]) == None
  example most_frequent([1]) == Some(1)
  example most_frequent([1, 2, 2, 3]) == Some(2)
  example most_frequent([5, 5, 5, 1, 1]) == Some(5)
{
  match xs {
    [] => None
    [h, ..t] => Some(find_most_in_list(xs, xs))
  }
}

