fn zip_sum(xs: List[Int], ys: List[Int]) -> List[Int]
  requires len(xs) == len(ys)
  ensures len(result) == len(xs)
  ensures len(result) == len(ys)
  effects pure
  example zip_sum([], []) == []
  example zip_sum([1, 2, 3], [10, 20, 30]) == [11, 22, 33]
  example zip_sum([5], [10]) == [15]
  example zip_sum([1, 2], [3, 4]) == [4, 6]
{
  match xs {
    [] => []
    [h_x, ..t_x] => 
      match ys {
        [h_y, ..t_y] => [h_x + h_y] ++ zip_sum(t_x, t_y)
        _ => []
      }
  }
}

